INSERT INTO app_redacto.assets (id, created, asset_id, asset_type) VALUES ('a77c0216-919f-4dfb-ba52-4bf3a185d43d', '2026-09-28 12:01:59.580', '8d07d1f7-3f57-41ae-8318-3dce1fb2812b', 'TEXT');
INSERT INTO app_redacto.assets (id, created, asset_id, asset_type) VALUES ('50132c05-7bdb-465f-b0a4-0f6923526e56', '2026-09-28 12:01:59.580', '68bb32f6-08cd-4acc-aef8-1750623e9b43', 'TEXT');
INSERT INTO app_redacto.assets (id, created, asset_id, asset_type) VALUES ('8822faa1-fcb0-408d-8b11-72ba547a330d', '2026-09-28 12:01:59.580', 'df0bdd5e-5973-49d1-8ac3-998dacfb1bbd', 'TEXT');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b2f7fe1c-63cd-48c3-b3b6-46a1ca6bcc37', '2026-09-28 12:01:59.580', 'en', 1, 'DRAFT', '<h1>Investing in US Securities – Qualified Intermediary (QI) Rules for Partnerships/Trusts under US QI</h1>', '757a339f-00c7-4f62-b055-5bc8d86bf4b5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('27096708-aab0-471a-9a8c-619fed081a2a', '2026-09-28 12:01:59.580', 'en', 1, 'DRAFT', '<h2>Background</h2>', 'c6c85f3d-e155-49f1-abb1-064a86c3643c');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('aec63b88-1d4c-4e35-9261-6515ef4857a1', '2026-09-28 12:01:59.580', 'en', 1, 'DRAFT', '<p>A partnership as well as &#39;grantor&#39; or &#39;simple&#39; trust will have to satisfy all the following conditions:</p>', 'b5bf2d01-dbff-4bfa-9ed6-daefc281ad73');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('fa680f82-2cb5-48a1-9b3a-c5dd1f748e7b', '2026-09-28 12:01:59.580', 'en', 1, 'DRAFT', '<ul><li>The partnership or trust is a direct account holder of UBS;</li><li>The account holder is a certified deemed-compliant FFI (other than a registered deemed-compliant Model 1 IGA FFI)<sup><a href="#footnote-1">1</a></sup>, an exempt beneficial owner, an owner-documented FFI or an NFFE (other than a Withholding partnership or trust).</li><li>None of the partners, beneficiaries or owners is a US person;</li><li>None of the partners, beneficiaries or owners are flow-through entities or acting as intermediaries; and</li><li>None of the partners, beneficiaries or owners is subject to FATCA withholding or reporting<sup><a href="#footnote-2">2</a></sup>.</li></ul>', '7ca256ad-930b-4952-a3f9-028b6d5d3601');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9d3210e7-cb53-4788-917e-6a02f9f66706', '2026-09-28 12:01:59.580', 'en', 1, 'DRAFT', '<p>The QI must withhold tax at the highest rate applicable to any partner, beneficiary, or owner.</p>', '992d8b22-b5ae-4d73-bfa0-dd799b7a7dc3');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d0004a13-d45e-4a97-857d-3c77097e6d0a', '2026-09-28 12:01:59.580', 'en', 1, 'DRAFT', '<h2>Documentation Required    </h2>', '55632855-67d3-4ee8-99e9-dd757b25aa27');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('5508fd25-69c0-49c6-930c-d5a30d86cf48', '2026-09-28 12:01:59.580', 'en', 1, 'DRAFT', '<p>In order to comply with the above conditions, the following specific QI documents are required from the partnership or trust:</p>', '2a18a90c-13e1-42cc-966f-d43f6a5e0de7');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('65306dc3-ef7d-456c-a503-67a0b6a86490', '2026-09-28 12:01:59.580', 'en', 1, 'DRAFT', '<ul><li>Withholding Statement and Agreement; and</li><li>Substitute Form W-8IMY from the partnership or trust; and</li><li>Official Form W-8BEN from each of the partners, beneficiaries or owners that are individuals; and/or</li><li>Official Form W-8BEN-E from each of the partners, beneficiaries or owners that are entities.</li></ul>', 'a86d67b0-0b55-4276-84cb-bf2896b00662');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('c26dedfc-c773-472e-bd8f-8723be66d346', '2026-09-28 12:01:59.580', 'en', 1, 'DRAFT', '<p>Please note that the above documents are kept within the bank and are not forwarded to the Internal Revenue Service.</p>', '00928a1a-370b-4273-95f6-fb1c784c85e9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('b6b39a0d-9f83-4d2a-b0f4-bc60327a9ee7', '2026-09-28 12:01:59.580', 'en', 1, 'DRAFT', '<h2>Risk of Non-Compliance</h2>', '15c35f0f-8993-4ce3-93bf-529df5aaf7a9');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('33337301-5abd-4ea4-8c6a-be33e13b3e9e', '2026-09-28 12:01:59.580', 'en', 1, 'DRAFT', '<p>Under the Withholding Statement and Agreement, the partnership or trust must make records available within 90 days upon request from</p>', 'e9e1e8d4-a72d-4ef4-9cee-25a2f3fe1777');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('13d4f3bb-0dd4-4f3c-8f7d-0873ccdfb9c2', '2026-09-28 12:01:59.580', 'en', 1, 'DRAFT', '<p>QI or QI&#39;s auditor. If the partnership or trust fails to comply with the request within the time limit, this might result in correction of withholding and disclosure of the partnership or trust and its partners, beneficiaries or owners to the US Internal Revenue Service.</p>', '8057d6ad-fdd7-4ebb-a502-59efd411197e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d85e0a39-d661-4386-9840-054f217febb8', '2026-09-28 12:01:59.580', 'en', 1, 'DRAFT', '<p>The Substitute Form W-8IMY and agreement are in general valid without timely restriction. Other documentation such as Forms W-8BEN and/or W-8BEN-E, withholding statements, and related documentation are subject to a renewal based on applicable rules, and unless there are material changes which will require a renewal. We appreciate that the QI rules are complicated. If you are not familiar with the QI rules, please seek advice from your own legal counsels for the appropriate action that you should take.</p>', '95f0ef6d-d465-4b65-9da1-511cac24878a');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('1d89b9f8-0a31-496d-9b06-3913d619dba8', '2026-09-28 12:01:59.580', 'en', 1, 'DRAFT', '<p>The information provided in this document is based on the current legal and/or tax laws as applicable at the point in time when this information was prepared. Such legal and/or tax situation may change subsequently. Please note that all legal and/or tax considerations and indications included in or deriving from the information provided in this document should only be considered as non-binding, general information. In no circumstance must such considerations and indications be understood as a substitute for having obtained appropriate legal and/or tax advice as provided by your certified legal and/or tax counsel. Only such counsel will be able to finally and comprehensively analyze your specific case and to take fully into account your individual situation. UBS Europe SE must not provide legal and or tax advice.</p>', '1bd68195-3f4e-4d7e-ad15-13c4b3324640');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('2e77f80b-de9f-4100-830c-c5bfa01cf38f', '2026-09-28 12:01:59.580', 'en', 1, 'DRAFT', '<p>UBS Europe SE is a subsidiary of UBS AG, Switzerland. Please note that this document must neither be copied nor distributed without having obtained the prior written approval from UBS Europe SE.</p>', '5342b4ec-d928-436a-9653-04693ecc084e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('19a5e5b3-2fda-4dec-97e7-5f9d205e8ae1', '2026-09-28 12:01:59.580', 'en', 1, 'DRAFT', '<p id="footnote-1"><sup>1</sup> The term &quot;certified deemed-compliant FFI (other than a registered deemed-compliant Model 1 IGA FFI)&quot; means certified deemed-compliant FFIs under the US FATCA regulations or a Model 2 IGA as well as nonreporting Model 1 IGA FFIs without an equivalent that is treated as a registered deemed-compliant FFI under the US FATCA regulations.</p>', '0f73ef8e-e6cd-49db-b660-d05f70974e39');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d6777b20-31f8-4626-9c27-b39dbd8f108e', '2026-09-28 12:01:59.580', 'en', 1, 'DRAFT', '<p id="footnote-2"><sup>2</sup> A partner, beneficiary or owner may be subject to FATCA withholding or reporting if, for example, it is a nonparticipating FFI or a passive NFFE with US controlling persons.</p>', 'a77c0216-919f-4dfb-ba52-4bf3a185d43d');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('76108c2a-a1b8-4aaa-8458-2705a96bcf9a', '2026-09-28 12:01:59.580', 'en', 1, 'DRAFT', '<div class="right preserve-spaces"><p>Gültig ab 02.01.2018</p><p>UBS Europe SE</p></div>', '50132c05-7bdb-465f-b0a4-0f6923526e56');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('632a098e-3f20-4d2c-9e05-addc67daa27f', '2026-09-28 12:01:59.580', 'en', 1, 'DRAFT', '<span class="redacto-reading-order"><span class="footer-form-id">66300</span> <span class="footer-language">EN</span> <span class="footer-version">V0</span> <span class="footer-man-code">019</span> <span class="footer-form-code">AAEV</span> <span class="footer-release-date">31.10.2019</span> <span class="footer-j-version">N1</span></span><span class="right">Page <span class="page-number"></span>/<span class="page-count"></span></span>', '8822faa1-fcb0-408d-8b11-72ba547a330d');
